<?php
 namespace OSS\Model; class ObjectVersionInfo { public function __construct($key, $versionId, $lastModified, $eTag, $type, $size, $storageClass, $isLatest) { $this->key = $key; $this->versionId = $versionId; $this->lastModified = $lastModified; $this->eTag = $eTag; $this->type = $type; $this->size = $size; $this->storageClass = $storageClass; $this->isLatest = $isLatest; } public function getKey() { return $this->key; } public function getVersionId() { return $this->versionId; } public function getLastModified() { return $this->lastModified; } public function getETag() { return $this->eTag; } public function getType() { return $this->type; } public function getSize() { return $this->size; } public function getStorageClass() { return $this->storageClass; } public function getIsLatest() { return $this->isLatest; } private $key = ""; private $versionId = ""; private $lastModified = ""; private $eTag = ""; private $type = ""; private $size = 0; private $storageClass = ""; private $isLatest = ""; }